/** Ordered browser preferences; no network, geolocation or identity inference. */
export function browserLanguages() {
    if (typeof navigator === 'undefined')
        return [];
    return [...(Array.isArray(navigator.languages) ? navigator.languages : []), navigator.language].filter(v => typeof v === 'string' && v.length > 0);
}
export function detectLocale(setting, languages = browserLanguages()) {
    if (['en', 'zh-Hans', 'zh-Hant'].includes(setting))
        return setting;
    for (const raw of languages) {
        if (typeof raw !== 'string')
            continue;
        const parts = raw.trim().replace(/_/g, '-').toLowerCase().split('-');
        if (parts[0] === 'en')
            return 'en';
        if (parts[0] !== 'zh')
            continue;
        // Explicit script wins over a region; zh-Hans-HK is deliberately Simplified.
        if (parts.includes('hant'))
            return 'zh-Hant';
        if (parts.includes('hans'))
            return 'zh-Hans';
        if (parts.some(v => ['tw', 'hk', 'mo'].includes(v)))
            return 'zh-Hant';
        return 'zh-Hans';
    }
    return 'en';
}
