export function toTraditional(input) {
    let out = input;
    for (const [from, to] of Object.entries(HANT_PHRASES).sort((a, b) => b[0].length - a[0].length))
        out = out.split(from).join(to);
    for (const [from, to] of HANT_CHAR_PAIRS)
        out = out.split(from).join(to);
    return out;
}
